programs.haiku:
"""The 'of' feature. The component fires on the word "of" when it links a noun or quantity to
the phrase after it, the partitive or measure "of" of "most of them", "a lot of", "the amount
of", "a piece of", "the rest of". It is strongest there, weaker after fixed prepositional
phrases such as "instance of", "out of", "because of" or "capable of", and weaker still on
the Romance and Dutch equivalents (de, di, van, del, ...). Zero on every other token.
Predicted values are the typical activation for each case, read off the component's own
activations on training text."""

READS = ()

# Quantity, part and measure nouns and words that take a partitive "of": "some of", "amount of".
PARTITIVE = {
    "some", "many", "most", "all", "each", "any", "both", "none", "neither", "either", "several",
    "few", "rest", "majority", "minority", "portion", "percent", "percentage", "half", "group",
    "pair", "one", "two", "three", "much", "more", "number", "fraction", "proportion",
    "remainder", "bulk", "amount", "sum", "size", "range", "ratio", "share", "level", "degree",
    "extent", "scope", "total", "bunch", "lot", "couple", "variety", "combination", "quality",
    "set", "series", "piece", "pieces", "part", "parts", "result", "results", "outcome", "lack",
    "cluster", "handful", "dozen", "dozens", "thousands", "hundreds", "millions", "snippet",
    "area", "areas",
}
# Fixed phrases where "of" is part of a preposition: "out of", "instance of", "because of".
FIXED = {
    "out", "instance", "instead", "because", "full", "consist", "consists", "consisting",
    "made", "composed", "capable", "accused", "spoke", "speaking", "heard", "think", "thought",
    "aware", "regardless",
}
OF_SPACED = {" of", " Of", " OF"}
OF_GLUED = {"of", "Of"}
OTHER_OF = {" de", " di", " van", " del", " della", " dei", " degli", " delle", " dell", " von"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in OF_SPACED:
        word = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
        if word in PARTITIVE:
            return carry, 9.5
        if word in FIXED:
            return carry, 2.4
        return carry, 6.8
    if tok in OF_GLUED or tok in OTHER_OF:
        return carry, 2.7
    return carry, 0.0

"""Component p-82af68dd layers.15.mlp.down_proj:1175, a verify/compare word detector.

This component is layer 15's MLP hidden unit 1175 (its dominant direction), read through
down_proj. Its activation is mostly diffuse and depends on context, with heavy tails. The
large negative values come on words that test or relate one thing to another: "assert",
"match", "comparison", "consistent", "compare", "between", "if", "whether", "check".

This program predicts a negative value on those cue words, a smaller one on the two tokens
after them, a small positive baseline elsewhere, and zero on a document's first token.
Its strength is the sign and rough size of the tails, not the detail of each value.
"""

READS = ()

# Cue words, grouped by how negative they usually are.
STRONG = {
    "assert", "match", "matches", "matching", "matched", "comparison", "contrad", "consistent",
}
MEDIUM = {
    "compare", "compared", "difference", "equal", "equals", "align", "verify", "between",
    "expect",
}
WEAK = {"if", "whether", "check", "checking", "fit", "expected", "correct"}

BASELINE = 0.035  # the component's mean activation
DECAY = (1.0, 0.5, 0.25)  # weight of a cue on the same token, one token later, two tokens later


def cue_value(word):
    """Typical activation contributed by one word."""
    if word in STRONG:
        return -1.5
    if word in MEDIUM:
        return -0.7
    if word in WEAK:
        return -0.35
    return 0.0


def step(carry, prefix, upstream):
    """Activation at the newest token: baseline, plus decayed cue values of the last 3 tokens."""
    t = prefix.position
    docs = prefix.document_ids
    if t == 0 or docs[t] != docs[t - 1]:
        return carry, 0.0  # a document's first token: the activation is about zero
    value = BASELINE
    for back, weight in enumerate(DECAY):
        j = t - back
        if j < 0 or (j > 0 and docs[j] != docs[j - 1]):
            break
        value += weight * cue_value(prefix.token_strings[j].strip().lower())
    return carry, float(value)

"""Copula / passive-auxiliary detector (layer 15 MLP down_proj, component 1179).

The component fires on forms of the verb "to be" (is, was, be, been, were, are,
being, am, and their contractions) and on the copulas of a few other languages
(ser, est, essere, sono, ist, ...). These are the words that set up a predicate:
a passive participle ("is used", "can be modelled") or an adjective ("is crucial").

Strength follows the context of the copula:
  - after a modal ("can be", "should be", "must be") it is strongest;
  - after an existential or demonstrative subject ("there is", "this is") it is weak;
  - otherwise it is medium.

An adverb sitting directly after a copula ("is often used", "was originally
built", "is not") also fires a little, because it is still waiting for its
participle. Everything else is predicted as 0.

This is a word-class rule, not the model's own computation: it gets about 40% of
the variance of the activation. A per-token lookup table would get about 50%.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

COPULA = {
    " is", " was", " be", " been", " were", " are", " being", " am",
    "'re", "'m", "’re", "’m",
    " ser", " est", " era", " sono", " è", " é", " ist", " essere", " être", " sont",
}
MODALS = {" can", " should", " must", " may", " could", " will", " shall", " might", " would"}
EXISTENTIAL = {" there", "There", " this", "This", " that", "That", " here", "here"}
ADVERBS = {
    " often", " also", " not", " never", " originally", " ever", " then", " usually",
    " typically", " always", " still", " already", " actually",
}


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    if token in COPULA:
        if before in EXISTENTIAL:
            return carry, 1.5
        if before in MODALS:
            return carry, 7.5
        return carry, 6.0
    if token in ADVERBS and before in COPULA:
        return carry, 4.0
    return carry, 0.0

"""Discourse "aspect opener" rules for component layers.15.mlp.down_proj:1181.

What it is: a rank-one piece of layer 15's MLP down projection. Its input weight sits
mostly on MLP hidden unit 1181 of that layer, and its output direction promotes words such
as "part", "portion", "aspect" and "方面". So its large positive activations come on the
words that open a discussion of one aspect of a topic: "As [for] ...", "[Regarding] ...",
a sentence-initial "For ...", "In [terms] of", and ordinals like "the [second]", "the
[last]", "the [latter]". Its activation is weakly negative in TODO-style notes and in code
comments.

What this program does: it applies those few word rules to the newest token and its two
predecessors (only within the same document) and returns the value each rule's cases had on
training text. Everywhere else it predicts 0.

Limits: these rules explain well under 1% of the variance. Most of the component's
activation (values between about -2 and 2) is not tied to any word, previous word, position
or repetition, and a linear model on the 32 preceding tokens reaches only about 1% on held-out
text. The rules are a readable summary of the rare large positive cases, not a fit to the bulk.
"""

READS = ()

ORDINALS = {"second", "third", "last", "latter", "former", "final", "first"}
CODE_MARKS = {"//", "#", "##", "###", "/*"}


def _tok(prefix, back):
    """The token `back` positions before the newest one, lowercased and stripped, or ''
    where that position is before the document's first token."""
    i = len(prefix.token_ids) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    cur, prev = _tok(prefix, 0), _tok(prefix, 1)
    if cur == "for" and prev == "as":
        value = 3.9  # "As for ..."
    elif cur == "regarding":
        value = 1.3
    elif cur == "for" and prev in {"", ".", "\n", "\n\n"}:
        value = 1.0  # a sentence-initial "For ..."
    elif prev == "regarding":
        value = 0.8
    elif cur == "terms" and prev == "in":
        value = 0.4  # "In terms of ..."
    elif cur in ORDINALS:
        value = 0.3  # "the second", "the last", ...
    elif cur in {"todo", "changes"} or prev in CODE_MARKS:
        value = -0.12  # notes and code comments
    else:
        value = 0.0
    return carry, value

"""Activation of layers.15.mlp.down_proj component 1188 (MLP hidden unit 1188 of layer 15).

What the component does, as far as a short program can say: it is a sparse, mostly
context-driven feature. Its activation is near zero (about -0.06) almost everywhere,
and it spikes positive (up to about 20) on a small share of tokens, usually where
the text is starting a new point in a structured or enumerated passage. The spikes
do not follow any token identity (a per-token lookup explains under 1% of the
variance) and no simple context rule explains most of them. This program captures
only the readable part of the pattern:

  - a sequence opener ("First", "首先", "Starting", "Regarding") gives a large rise;
  - a markdown heading marker ("#", "##", "###") gives a moderate rise;
  - a list cue word in the few tokens before ("the following", "three", "steps",
    "ways", "reasons") gives a small rise;
  - the first token of a line gives a small rise;
  - otherwise the activation sits at its typical resting value.

The weights are rounded from a least-squares fit of these features on 16k training
rows (the fit also had a digit term, dropped here as negligible). Measured on eval, the
variance explained is about 0.2%: most of the component's variance is not captured by
these rules, and a full linear readout of the residual stream reaches only about 15%.
"""

READS = ()

REST = -0.065
"""The typical activation away from any cue."""

OPENERS = {"first", "firstly", "首先", "其次", "starting", "regarding", "among"}
"""Words that open an ordered sequence of points."""

LIST_CUES = {
    "first", "second", "three", "two", "several", "following", "ways", "steps",
    "types", "reasons", "advantages", "disadvantages", "methods", "以下", "如下", "其中",
}
"""Words that announce a list of parts that is about to be enumerated."""

WINDOW = 12
"""How many recent tokens count as the context of a list cue."""


def _is_heading(text):
    """A markdown heading marker: only '#' characters (possibly with '*')."""
    core = text.strip()
    return "#" in core and set(core) <= set("#*")


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings[-WINDOW:]]
    current = words[-1]
    value = REST
    if current in OPENERS:
        value += 0.57
    if _is_heading(prefix.token_strings[-1]):
        value += 0.27
    if set(words[:-1]) & LIST_CUES:
        value += 0.02
    if prefix.position == 0 or "\n" in prefix.token_strings[-2]:
        value += 0.05
    return carry, float(value)

"""Layer 15 MLP down_proj, component 1201: a "reproduce / ease / ability" word feature.

Plain-terms summary. The component is switched on by a few kinds of word:
  * strongest: words for reproducing or copying something, "reproduce", "reproduction",
    "replicate", "reconstruct", "recreate" (and their word pieces "repro", "duc", "cing").
    The logit lens of its output direction promotes exactly these words (reproduce,
    replicate, recreate, clone), and its largest activations (up to about 35) sit on them;
  * weaker: other words of replicating or serializing ("replication", "reproducible",
    "serialize", "seed");
  * words of ease, skill or understanding: "easy", "easily", "readily", "skilled",
    "understand", "verify", "confirm", "execute";
  * a function word that leads into a verb ("to", "can", "be", "could", "will", "would",
    "not") right after an ability word, as in "easy to", "able to", "possible to", "way to";
  * a faint positive on those same function words elsewhere;
  * weakly negative on apology and politeness words ("sorry", "please", "sure", "hope").

Only a small part of the component's variance is in these words. Most of its activity is a
diffuse background of typical size 0.5 that no short word rule captures, so this program
explains very little variance. It is a readable account of the word-driven spikes, not of
the whole signal.
"""

import re

READS = ()

STRONG = re.compile(
    r"^(reproduce|reprodu|reproduced|reproduction|repro|duc|cing|replicate|produce|roduce"
    r"|recre|recreate|reconstruct)$"
)
WEAK = re.compile(r"repro|replic|recre|reconstruct|serializ|duplicat|clone|seed", re.I)
EASE = {
    "easy", "easily", "readily", "skilled", "skill", "ordinary", "accurately", "reliably",
    "understand", "understood", "understandable", "verify", "confirm", "execute", "locate",
    "explain", "download",
}
ABILITY = {"easy", "able", "possible", "ability", "way", "ways", "order", "access", "difficult"}
FUNCTION = {"to", "can", "be", "could", "will", "would", "not"}
POLITE = {"sorry", "please", "sure", "hope", "glad", "thanks", "apologize"}

VALUE = {"strong": 2.5, "weak": 0.4, "ease": 0.7, "after_ability": 0.6, "function": 0.1, "polite": -0.3}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    word = _word(prefix.token_strings[t])
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    prev = _word(prefix.token_strings[t - 1]) if same_doc else ""
    if STRONG.search(word):
        value = VALUE["strong"]
    elif WEAK.search(word):
        value = VALUE["weak"]
    elif word in EASE:
        value = VALUE["ease"]
    elif word in FUNCTION and prev in ABILITY:
        value = VALUE["after_ability"]
    elif word in FUNCTION:
        value = VALUE["function"]
    elif word in POLITE:
        value = VALUE["polite"]
    else:
        value = 0.0
    return carry, float(value)

"""Predicate-verb detector (layer 15 MLP, component 1205).

What it does: this component is positive on the verb that carries a clause's predicate,
mainly modals and present-tense verbs that come straight after their subject
("It can ...", "This provides ...", "Analysis shows ..."), and negative on nouns and
adjectives, most of all after a determiner or preposition ("the test", "in data").
Verbs after "to" or "be" are weaker, and commas are mildly positive. Other tokens sit near 0.

The numbers in TABLE are the mean activation for each kind of word, given what came just
before it, averaged over about 8 million training tokens. The program reads only the
previous token and the current word, and uses WordNet to tell verbs from nouns.
"""

import wordnet

READS = ()

MODAL = {"will", "can", "may", "must", "could", "would", "should", "might", "shall",
         "has", "have", "had", "does", "did", "do"}
BE = {"is", "are", "was", "were", "be", "been", "am", "being"}
PRONOUN = {"it", "they", "he", "she", "we", "you", "i", "this", "which", "who", "that",
           "there", "one", "these", "those"}
DETERMINER_PREP = {"the", "a", "an", "of", "in", "for", "as", "by", "on", "at", "with",
                   "from", "into", "its", "their", "his", "her", "our", "my", "your",
                   "all", "some", "any", "each", "every", "no"}
COMMA = {",", "，", "、"}

# Mean activation by (kind of word, what precedes it).
TABLE = {
    "modal": {"subject": 2.0, "det": 0.4, "to": 0.4, "other": 2.0},
    "be": {"subject": 0.7, "det": 0.0, "to": -0.5, "other": 0.4},
    "verb_s": {"subject": 2.5, "det": -0.5, "to": 0.8, "other": 2.2},
    "verb": {"subject": 1.6, "det": 0.0, "to": 0.6, "other": 0.9},
    "verb_or_noun": {"subject": 0.6, "det": -0.4, "to": 0.4, "other": 0.25},
    "noun_adj": {"subject": -0.2, "det": -0.3, "to": -0.3, "other": -0.2},
    "comma": {"subject": 0.6, "det": 0.6, "to": 0.6, "other": 0.6},
    "other": {"subject": 0.0, "det": -0.1, "to": -0.1, "other": -0.05},
}


def kind(token):
    """What sort of word the token is: a modal, a form of 'be', a verb (ending in -s or
    not), a word that is both verb and noun, a noun or adjective, a comma, or other."""
    word = token.strip().lower()
    if token.startswith(" ") and word in MODAL:
        return "modal"
    if token.startswith(" ") and word in BE:
        return "be"
    if token.strip() in COMMA:
        return "comma"
    if token.startswith(" ") and word.isalpha():
        pos = wordnet.parts_of_speech(word)
        if pos == {"verb"}:
            return "verb_s" if word.endswith("s") else "verb"
        if "verb" in pos:
            return "verb_or_noun"
        if pos:
            return "noun_adj"
    return "other"


def before(previous):
    """What came just before: a subject (pronoun or noun), a determiner or preposition,
    'to', or something else."""
    word = previous.strip().lower()
    if word in PRONOUN:
        return "subject"
    if word in DETERMINER_PREP:
        return "det"
    if word == "to":
        return "to"
    if previous.startswith(" ") and word.isalpha() and wordnet.parts_of_speech(word) == {"noun"}:
        return "subject"
    return "other"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return None, TABLE[kind(token)][before(previous)]

"""Layer 15 MLP down_proj, component 1206.

What it does: this component writes a strong signal for two kinds of words.
  * Negative on "both"-type quantifiers that refer to a pair ("both", "either",
    "neither", "two", and their German/French/Spanish/Chinese equivalents).
    "both" is the strongest, about -3 to -4 in the decomposition's own high-CI cases.
  * Positive on words that pair items up one-to-one or mark a matched list:
    "respectively" (the strongest), "aligned", "分别", "respective",
    "corresponding", and "array".
Everywhere else it is near zero, with diffuse noise (about 0.4 RMS) that no
token rule predicts, so the program predicts 0 there.

The program looks only at the current token; no state is carried.
"""

# Quantifiers that refer to a pair of things, with a typical activation.
BOTH = {" both", " Both", "both", "Both"}
EITHER = {" either", " Either", " neither", " Neither"}
TWO = {" two", " deux", " zwei", " beide", " ambos", "两", "两个", "这两"}

# Words that pair items up one-to-one or mark a matched list.
RESPECTIVE = {" respectively", " respective", "分别", " corresponding"}
ALIGNED = {"aligned", "array", " array"}

VALUE = {}
for _w in BOTH:
    VALUE[_w] = -3.0
for _w in EITHER:
    VALUE[_w] = -1.5
for _w in TWO:
    VALUE[_w] = -1.0
for _w in RESPECTIVE:
    VALUE[_w] = 2.5
VALUE[" respectively"] = 4.0
for _w in ALIGNED:
    VALUE[_w] = 2.0


READS = ()


def step(carry, prefix, upstream):
    """This component's activation at the current position: a fixed value per word, else 0."""
    return carry, VALUE.get(prefix.token_strings[-1], 0.0)
